insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_95_v1'
from (values
('127.748.d.1.A',3,'A fire company officer gives clear spoken orders at a scene and writes a short log afterward. This demonstrates:','["speech and written communication platforms common to fire management", "silence", "guesswork", "graffiti"]'::jsonb,0,'Fire management relies on spoken and written communication.','original'),
('127.748.d.1.A',4,'Why do fire departments require written incident logs?','["They decorate the station", "They record what happened for review, training and legal needs", "They replace radios", "They are never read"]'::jsonb,1,'Logs document actions and decisions.','original'),
('127.748.d.1.B',3,'A firefighter keys the radio, states the unit name, then gives a short clear message and waits for acknowledgment. This is:','["random chatter", "avoiding contact", "the steps for using radio communication in fire management", "shouting"]'::jsonb,2,'Radio use follows a set format.','original'),
('127.748.d.1.B',4,'Which radio habit helps messages be understood at a loud fire scene?','["Whisper", "Use private slang", "Mumble quickly", "Speak slowly and clearly using plain language"]'::jsonb,3,'Clarity prevents errors.','original'),
('127.748.d.1.C',3,'At a large fire, one officer is in charge and divides tasks among sections such as operations and logistics. This is the:','["Incident Command System", "Air bottle", "Fire triangle", "Hose lay"]'::jsonb,0,'ICS organizes emergency response.','original'),
('127.748.d.1.C',4,'The main benefit of using the Incident Command System is that it:','["ends training", "gives a clear chain of command and organized roles", "removes all risk", "eliminates radios"]'::jsonb,1,'ICS prevents confusion.','original'),
('127.748.d.1.D',3,'Firefighters arrive at a highway crash, place warning devices and protect the scene from traffic before helping the injured. This is applying:','["ignoring danger", "leaving the area", "protocols for working at an accident scene", "blocking help"]'::jsonb,2,'Scene protection comes first.','original'),
('127.748.d.1.D',4,'The first step at a vehicle accident scene is generally to:','["start paperwork", "move every car", "skip safety", "size up the scene and make it safe"]'::jsonb,3,'Safety first.','original'),
('127.748.d.2.A',3,'A station follows OSHA rules and the NFPA standards about protective gear. These are:','["local, state and federal regulations on safety", "suggestions", "parking tips", "menu rules"]'::jsonb,0,'Regulations set safety requirements.','original'),
('127.748.d.2.A',4,'Why must a fire department follow federal and state safety regulations?','["They are optional", "They reduce injuries and are legally required", "They save paper only", "They look good"]'::jsonb,1,'Compliance protects firefighters.','original'),
('127.748.d.2.B',3,'A first-arriving crew sees a tanker leaking an unknown liquid, stays back and calls for a hazmat team. This is:','["touching the liquid", "entering the spill", "awareness-level protocol for hazardous materials", "ignoring the leak"]'::jsonb,2,'Awareness-level responders identify and isolate, not clean up.','original'),
('127.748.d.2.B',4,'At the awareness level, firefighters are trained to:','["neutralize the chemical", "collect samples", "enter the leak", "recognize a hazardous material, isolate the area and call for help"]'::jsonb,3,'They protect the public and notify specialists.','original'),
('127.748.d.2.C',3,'Before a drill, a firefighter checks gear, hydrates and follows lifting rules. These are:','["personal safety procedures", "extra work", "wasted time", "optional steps"]'::jsonb,0,'Personal safety prevents injury.','original'),
('127.748.d.2.C',4,'Which personal safety practice reduces back injuries on the fireground?','["Carrying heavy gear one-handed", "Using proper lifting technique and team lifts", "Lifting alone with a twist", "Skipping stretching"]'::jsonb,1,'Technique protects the body.','original'),
('127.748.d.3.A',3,'A new recruit learns to listen, follow instructions and share tasks with her crew. This is:','["working alone", "avoiding feedback", "functioning within a group environment", "quitting"]'::jsonb,2,'Teamwork is essential in firefighting.','original'),
('127.748.d.3.A',4,'Which behavior best supports teamwork on a fire crew?','["Ignoring orders", "Competing for credit", "Working separately", "Communicating clearly and supporting crew members"]'::jsonb,3,'Cooperation improves safety.','original'),
('127.748.d.3.B',3,'A senior firefighter stays calm, sets an example in following safety rules and mentors a rookie. This demonstrates:','["model leadership in fire management", "showing off", "poor leadership", "avoidance"]'::jsonb,0,'Leaders lead by example.','original'),
('127.748.d.3.B',4,'A strong fire service leader shows leadership by:','["breaking rules", "acting with integrity and setting a good example", "avoiding training", "ignoring crew"]'::jsonb,1,'Integrity builds trust.','original'),
('127.748.d.4.A',3,'A recruit looks up the Texas rules that govern basic firefighter certification. This is identifying:','["menu rules", "parking rules", "the laws and rules for basic firefighter certification", "school rules"]'::jsonb,2,'Certification follows state rules.','original'),
('127.748.d.4.A',4,'Which agency''s rules apply to firefighter certification in Texas?','["Parks department", "State library", "Highway department", "Texas Commission on Fire Protection"]'::jsonb,3,'TCFP certifies Texas firefighters.','original'),
('127.748.d.4.B',3,'A trainee reads about the training hours and exams needed to become a certified firefighter. This is:','["reviewing Texas Commission on Fire Protection certification requirements", "ignoring exams", "skipping training", "avoiding rules"]'::jsonb,0,'Requirements include training and testing.','original'),
('127.748.d.4.B',4,'To become a certified Texas firefighter, a person must typically:','["only watch videos", "complete approved training and pass the required exams", "only apply", "only pay a fee"]'::jsonb,1,'Training and testing are required.','original'),
('127.748.d.4.C',3,'Basic, intermediate, advanced and master are examples of:','["truck models", "hose sizes", "firefighter certification levels", "school grades"]'::jsonb,2,'Certification has levels.','original'),
('127.748.d.4.C',4,'A higher firefighter certification level generally requires:','["no experience", "less training", "no testing", "more training, experience and education"]'::jsonb,3,'Higher levels demand more.','original'),
('127.748.d.4.D',3,'A firefighter earns a certificate to teach new recruits. This relates to:','["levels of instructor certification", "engine pumping", "radio frequency", "hose coupling"]'::jsonb,0,'Instructors have their own levels.','original'),
('127.748.d.4.D',4,'A person who wishes to teach at a fire academy must usually:','["avoid training", "hold instructor certification from the state", "have no experience", "be a visitor"]'::jsonb,1,'Instructors must be certified.','original'),
('127.748.d.4.E',3,'The NFPA sets standards for firefighter duties. A recruit who learns what she must be able to do on the job is studying:','["sports", "menu planning", "a firefighter''s responsibilities per NFPA standards", "fashion"]'::jsonb,2,'NFPA 1001 sets job performance requirements.','original'),
('127.748.d.4.E',4,'The NFPA is best known for developing:','["road maps", "tax rules", "recipes", "fire and life safety codes and standards"]'::jsonb,3,'NFPA publishes safety standards.','original'),
('127.748.d.5.A',3,'In a structure fire, smoke, heat and toxic gases are the products of combustion that can harm firefighters. These include:','["gases, flame, heat and smoke", "only water", "only wind", "only light"]'::jsonb,0,'Four products of combustion are gases, flame, heat and smoke.','original'),
('127.748.d.5.A',4,'Which is a dangerous product of combustion in a structure fire?','["fresh air", "carbon monoxide gas", "dust only", "water vapor only"]'::jsonb,1,'CO is a deadly gas.','original'),
('127.748.d.5.B',3,'The lowest temperature at which a liquid gives off enough vapor to ignite is its:','["boiling point only", "melting point", "flash point", "freezing point"]'::jsonb,2,'Flash point is a basic fire term.','original'),
('127.748.d.5.B',4,'Ignition temperature is the minimum temperature at which a substance will:','["freeze", "evaporate", "melt", "ignite and continue to burn without an outside flame"]'::jsonb,3,'Self-sustained ignition.','original'),
('127.748.d.5.C',3,'In a room fire, the hottest gases collect near the ceiling while cooler air stays near the floor. This is called:','["thermal layering", "backdraft", "flame spread only", "a hose lay"]'::jsonb,0,'Hot gases rise and form layers.','original'),
('127.748.d.5.C',4,'Why do firefighters stay low when moving through a smoky room?','["Smoke sinks to the floor", "Thermal layering puts the hottest gases high and cooler, clearer air low", "It is faster to crawl", "Gravity is stronger low"]'::jsonb,1,'Cooler air lies near the floor.','original'),
('127.748.d.5.D',3,'Oxygen, heat, fuel and a chemical chain reaction are the parts of the:','["wind square", "hose triangle", "fire tetrahedron", "ladder cube"]'::jsonb,2,'The tetrahedron adds the chain reaction.','original'),
('127.748.d.5.D',4,'Removing which part of the fire triangle will stop a fire?','["only the color", "only the smell", "only the sound", "fuel, oxygen or heat"]'::jsonb,3,'Remove one side.','original'),
('127.748.d.5.E',3,'A short in a wire that starts a fire is an example of an:','["electrical heat energy source", "mechanical source only", "nuclear source", "chemical source only"]'::jsonb,0,'Electrical energy can ignite materials.','original'),
('127.748.d.5.E',4,'Friction from two surfaces rubbing together producing heat is a:','["nuclear source", "mechanical heat energy source", "chemical source", "solar source"]'::jsonb,1,'Friction creates heat.','original'),
('127.748.d.5.F',3,'From incipient to growth, fully developed and decay, a fire passes through:','["traffic lights", "school grades", "stages of fire development", "moon phases"]'::jsonb,2,'Fire progresses through stages.','original'),
('127.748.d.5.F',4,'The stage of fire when it is just starting and still small is the:','["flashover", "fully developed stage", "decay stage", "incipient stage"]'::jsonb,3,'Incipient = beginning.','original'),
('127.748.d.5.G',3,'A sudden event in which all contents of a room ignite at once is called:','["flashover", "hydrant", "backdraft", "a thermal layer"]'::jsonb,0,'Flashover is a rapid transition.','original'),
('127.748.d.5.G',4,'When oxygen is suddenly introduced to an oxygen-starved fire and causes an explosion, it is called a:','["rollover", "backdraft", "draft", "flashover"]'::jsonb,1,'Backdraft is a violent explosion.','original'),
('127.748.d.5.H',3,'A British thermal unit and a calorie are both units of:','["speed", "distance", "heat measurement", "weight"]'::jsonb,2,'Both measure heat energy.','original'),
('127.748.d.5.H',4,'Converting between Fahrenheit and Celsius is an example of:','["measuring distance", "measuring weight", "measuring time", "converting units of temperature measurement"]'::jsonb,3,'Unit conversion is part of fire science.','original'),
('127.748.d.6.A',3,'Heat moving through a metal pipe from a fire to a wall is:','["conduction", "condensation", "convection", "radiation"]'::jsonb,0,'Conduction transfers heat by contact.','original'),
('127.748.d.6.A',4,'Heat carried by rising hot gases is called:','["radiation", "convection", "conduction", "insulation"]'::jsonb,1,'Convection moves heat through fluids.','original'),
('127.748.d.6.B',3,'A firefighter feels heat across a street from a burning building without touching it. This is an example of heat transfer by:','["convection", "conduction", "radiation", "absorption"]'::jsonb,2,'Radiation travels as waves.','original'),
('127.748.d.6.B',4,'A fire spreading to a neighboring house by heat waves across a gap is an example of:','["conduction through air", "water transfer", "convection through wood", "radiant heat transfer"]'::jsonb,3,'Radiant heat can ignite nearby structures.','original'),
('127.748.d.7.A',3,'Fuels commonly appear as solids, liquids or gases. These are:','["the physical states of matter in which fuels are found", "truck types", "wind types", "hose types"]'::jsonb,0,'Fuel state affects how it burns.','original'),
('127.748.d.7.A',4,'Gasoline in a tank is a fuel in which state of matter?','["solid", "liquid", "plasma", "none"]'::jsonb,1,'Gasoline is a liquid fuel.','original'),
('127.748.d.7.B',3,'Specific gravity and vapor density help firefighters predict whether a leaked vapor will sink or rise. These are terms related to:','["hose types", "truck parts", "the combustion process", "station design"]'::jsonb,2,'They describe fuel behavior.','original'),
('127.748.d.7.B',4,'A vapor with a density greater than air will usually:','["freeze", "rise to the ceiling", "vanish", "sink and collect in low areas"]'::jsonb,3,'Heavier vapors pool low.','original'),
('127.748.d.7.C',3,'Carbon monoxide and hydrogen cyanide are dangerous gases found in smoke because they:','["poison people and reduce oxygen use by the body", "smell like flowers", "cool the room", "are harmless"]'::jsonb,0,'They are asphyxiants.','original'),
('127.748.d.7.C',4,'An irritant gas in smoke would most likely cause:','["faster breathing only", "burning eyes and coughing", "no effect", "improved vision"]'::jsonb,1,'Irritants affect eyes and airways.','original'),
('127.748.d.8.A',3,'Fire extinguishment theory says a fire can be put out by removing one or more parts of the:','["roof", "hydrant", "fire triangle or tetrahedron", "engine"]'::jsonb,2,'Remove heat, fuel, oxygen or the reaction.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_95_v1'
from (values
('127.748.d.8.A',4,'Which statement fits extinguishment theory?','["Fires only need heat", "Fires always go out on their own", "Fires need no fuel", "A fire goes out when one of its essential elements is removed"]'::jsonb,3,'Remove a side of the triangle.','original'),
('127.748.d.8.B',3,'Spraying water on a fire cools it. This is a method of extinguishment called:','["temperature reduction", "fuel removal", "chain breaking", "oxygen exclusion"]'::jsonb,0,'Cooling removes heat.','original'),
('127.748.d.8.B',4,'Closing a valve to stop gas flowing to a burning pipe is an example of:','["temperature reduction", "fuel removal", "oxygen exclusion", "chain inhibition"]'::jsonb,1,'Remove the fuel.','original'),
('127.748.d.9.A',3,'The amount of heat needed to raise the temperature of a substance is described by its:','["speed", "color", "specific heat", "pressure"]'::jsonb,2,'Specific heat is a thermodynamics concept.','original'),
('127.748.d.9.A',4,'Latent heat is the energy that is absorbed or released when a substance changes:','["name", "weight only", "color", "state, such as water to steam"]'::jsonb,3,'Latent heat accompanies phase changes.','original'),
('127.748.d.9.B',3,'Water absorbs a great deal of heat and expands when it turns to steam. This is an advantage of water because it:','["cools well and is widely available", "burns", "is a fuel", "removes oxygen only"]'::jsonb,0,'Water cools efficiently.','original'),
('127.748.d.9.B',4,'A disadvantage of using water on a fire involving live electrical equipment is that water can:','["help the fire", "conduct electricity and create a shock hazard", "vanish", "freeze"]'::jsonb,1,'Water conducts electricity.','original'),
('127.748.d.10.A',3,'The respiratory and circulatory systems supply the body with oxygen. A firefighter studies these because:','["they are fire fuel", "they are unimportant", "breathing apparatus protects these life-sustaining systems", "they are decorative"]'::jsonb,2,'Understanding the body supports safe SCBA use.','original'),
('127.748.d.10.A',4,'Which body system carries oxygen from the lungs to the rest of the body?','["digestive system", "nervous system only", "skeletal system", "circulatory system"]'::jsonb,3,'Blood carries oxygen.','original'),
('127.748.d.10.B',3,'A department follows national standards for choosing and maintaining breathing apparatus. These are:','["NFPA standards for SCBA selection, care and maintenance", "menu standards", "sports standards", "parking standards"]'::jsonb,0,'NFPA addresses SCBA.','original'),
('127.748.d.10.B',4,'Why do departments follow NFPA standards for breathing apparatus?','["They limit training", "They help ensure the equipment protects firefighters", "They are never used", "They are decorations"]'::jsonb,1,'Standards ensure reliability.','original'),
('127.748.d.10.C',3,'Before wearing an SCBA, a firefighter must meet medical and fitness requirements. This identifies:','["no requirements", "only age", "the physical requirements for wearing an SCBA", "only uniform rules"]'::jsonb,2,'Wearing SCBA is demanding.','original'),
('127.748.d.10.C',4,'Which condition could make wearing an SCBA unsafe for a firefighter?','["short hair", "a loud voice", "tall height only", "a serious respiratory or heart problem"]'::jsonb,3,'Medical clearance is needed.','original'),
('127.748.d.10.D',3,'A burning building filled with smoke contains oxygen-poor air and toxic gases. These are:','["respiratory hazards that require breathing protection", "only water vapor", "pleasant smells", "harmless gases"]'::jsonb,0,'Smoke is hazardous to breathe.','original'),
('127.748.d.10.D',4,'Which firefighting condition most clearly requires a breathing apparatus?','["a sunny day", "a smoke-filled environment", "a clear field", "a paved road"]'::jsonb,1,'Smoke requires SCBA.','original'),
('127.748.d.10.E',3,'An open-circuit SCBA exhales into the air, while a closed-circuit unit recycles air. These are:','["types of hose", "types of ladders", "different types of self-contained breathing apparatus", "types of trucks"]'::jsonb,2,'Open and closed circuit.','original'),
('127.748.d.10.E',4,'The most common SCBA used in structural firefighting is the:','["dust mask", "scuba tank", "oxygen mask for pilots", "open-circuit SCBA"]'::jsonb,3,'Open circuit is standard.','original'),
('127.748.d.10.F',3,'An open-circuit SCBA has a pressure gauge, an alarm and a regulator. These are:','["safety features and functions of the unit", "cosmetic features", "unneeded parts", "toys"]'::jsonb,0,'Safety features warn the wearer.','original'),
('127.748.d.10.F',4,'The low-air alarm on an SCBA warns the firefighter that:','["the wind changed", "the air supply is running low and it is time to exit", "the battery is full", "the fire is out"]'::jsonb,1,'Low-air alarm triggers exit.','original'),
('127.748.d.11.A',3,'Before entering a smoky building, a firefighter checks the SCBA gauge, mask seal and alarm. This is following:','["wasted time", "optional steps", "safety requirements for using the breathing apparatus", "guesswork"]'::jsonb,2,'Pre-entry checks prevent failures.','original'),
('127.748.d.11.A',4,'A firefighter''s SCBA should be inspected for a full cylinder and a working alarm:','["only after a fire", "once a year only", "never", "before every use"]'::jsonb,3,'Check before use.','original'),
('127.748.d.11.B',3,'A 30-minute cylinder holds about 1,800 cubic feet of air, and a firefighter breathes 60 cubic feet per minute. Estimating how long the air lasts is:','["calculating the air supply duration", "guessing", "avoiding math", "ignoring the gauge"]'::jsonb,0,'1,800 ÷ 60 = 30 minutes.','original'),
('127.748.d.11.B',4,'A cylinder holds 1,200 cubic feet of air and a firefighter uses 40 cubic feet per minute. How long will the air last?','["1,160 minutes", "30 minutes", "48 minutes", "20 minutes"]'::jsonb,1,'1,200 ÷ 40 = 30.','original'),
('127.748.d.11.C',3,'One safety rule for wearing an SCBA is to never remove the facepiece while in a contaminated area. The reason is:','["it saves air", "it is a tradition", "toxic smoke can quickly cause serious injury", "it looks bad"]'::jsonb,2,'Facepieces protect the airway.','original'),
('127.748.d.11.C',4,'The buddy system when wearing SCBA means that firefighters:','["split up", "work alone", "avoid radios", "enter, work and leave together"]'::jsonb,3,'Buddies watch each other.','original'),
('127.748.d.11.D',3,'An SCBA provides clean air but does not protect against heat or cuts. This describes its:','["uses and limitations", "only uses", "no limits", "only color"]'::jsonb,0,'SCBA protects breathing only.','original'),
('127.748.d.11.D',4,'A limitation of an SCBA in a long rescue is that:','["it never runs out", "the air supply in the cylinder is limited", "it is weightless", "it cannot be seen"]'::jsonb,1,'Air supply is finite.','original'),
('127.748.d.11.E',3,'A firefighter practices putting on the SCBA over her coat and then removing it quickly after an exercise. This demonstrates:','["ignoring gear", "breaking gear", "donning and doffing the breathing apparatus", "avoiding training"]'::jsonb,2,'Donning methods are practiced.','original'),
('127.748.d.11.E',4,'When donning an SCBA, the facepiece should be checked for:','["bright color", "a name tag", "scratches only", "a proper seal before entering a hazard area"]'::jsonb,3,'A seal prevents smoke entry.','original'),
('127.748.d.11.F',3,'After a low-air alarm, a firefighter trades an empty cylinder for a full one at the rehab area. This is:','["replacing an expended cylinder", "changing a boot", "cleaning a helmet", "adding a hose"]'::jsonb,0,'Cylinder replacement is a skill.','original'),
('127.748.d.11.F',4,'When replacing an SCBA cylinder, the firefighter should always:','["use any cylinder", "check that the new cylinder is full and the connection is tight", "skip testing", "ignore leaks"]'::jsonb,1,'Verify the new cylinder.','original'),
('127.748.d.11.G',3,'A rescuer with an SCBA must reach an unconscious person without removing her own mask. This demonstrates:','["ignoring risk", "avoiding rescue", "rescue procedures that protect the rescuer''s breathing", "unsafe rescue"]'::jsonb,2,'The rescuer must keep their own air.','original'),
('127.748.d.11.G',4,'During a rescue in smoke, the firefighter''s top priority regarding her own air is to:','["remove the mask", "share her mask first", "ignore the gauge", "keep her facepiece on and monitor her supply"]'::jsonb,3,'Rescuers must not become victims.','original'),
('127.748.d.11.H',3,'A firefighter advances a hose line while wearing an SCBA. This is performing:','["firefighting skills while wearing the breathing apparatus", "sitting", "sports", "jogging only"]'::jsonb,0,'Tasks are performed in gear.','original'),
('127.748.d.11.H',4,'Compared with working without an SCBA, working with one usually:','["improves hearing", "adds weight and limits vision and movement", "makes the work lighter", "removes risk"]'::jsonb,1,'SCBA adds load and limits mobility.','original'),
('127.748.d.11.I',3,'A firefighter crawls through a tight space under a collapsed ceiling and has to use a technique to keep the SCBA from snagging. This is:','["avoiding tight spaces", "using no technique", "using the SCBA in a restricted space", "removing the gear"]'::jsonb,2,'Restricted spaces require special handling.','original'),
('127.748.d.11.I',4,'In a restricted opening, a firefighter might slip the SCBA off one shoulder while:','["dropping the cylinder", "removing the mask", "closing the valve", "keeping the facepiece on and staying connected to the air"]'::jsonb,3,'Maintain airway protection.','original'),
('127.748.d.11.J',3,'If an SCBA regulator suddenly stops delivering air, a firefighter follows emergency procedures such as bypass and calling a Mayday. This is:','["emergency procedures for SCBA failure", "waiting", "ignoring the problem", "removing the mask"]'::jsonb,0,'Failures require immediate action.','original'),
('127.748.d.11.J',4,'If an SCBA fails inside a burning building, the firefighter should first:','["hold her breath and stay", "activate the bypass, call for help and exit", "panic", "take off her coat"]'::jsonb,1,'Use emergency procedures.','original'),
('127.748.d.12.A',3,'A firefighter writes down the date a regulator was cleaned and a cylinder was tested. This is:','["skipping inspections", "avoiding records", "documenting routine SCBA maintenance", "hiding errors"]'::jsonb,2,'Records show equipment care.','original'),
('127.748.d.12.A',4,'Keeping a log of SCBA maintenance helps a department:','["avoid inspections", "hide damage", "raise costs", "prove equipment was inspected and serviced"]'::jsonb,3,'Records support safety and compliance.','original'),
('127.748.d.12.B',3,'A fill station compresses air and recharges SCBA cylinders at the firehouse. This is an:','["air supply system for recharging cylinders", "radio charger", "ladder rack", "hose washer"]'::jsonb,0,'Cascade or compressor systems refill cylinders.','original'),
('127.748.d.12.B',4,'The air used to fill SCBA cylinders must be:','["any air", "clean, dry breathable air tested to standards", "moist air", "smoky air"]'::jsonb,1,'Breathing air must meet quality standards.','original'),
('127.748.d.13.A',3,'Structural gear, wildland gear and proximity suits are different types of:','["uniforms for parades", "sports uniforms", "fire service protective clothing", "street clothes"]'::jsonb,2,'Different hazards need different gear.','original'),
('127.748.d.13.A',4,'Which type of protective clothing is designed to reflect extreme radiant heat near a large fire?','["a rain jacket", "a T-shirt", "a sweater", "a proximity suit"]'::jsonb,3,'Proximity suits reflect heat.','original'),
('127.748.d.13.B',3,'A helmet, hood, coat, pants, gloves and boots make up:','["structural firefighting protective equipment", "a school uniform", "a picnic set", "a sports kit"]'::jsonb,0,'The ensemble protects the body.','original'),
('127.748.d.13.B',4,'The hood in a structural firefighting ensemble protects:','["the feet", "the neck and ears not covered by the helmet or mask", "the knees", "the hands"]'::jsonb,1,'Hoods cover exposed skin.','original'),
('127.748.d.13.C',3,'After a fire, a firefighter looks for burns, tears and worn stitching on her coat and cleans it per procedure. This is:','["tossing gear", "ignoring gear", "inspecting and maintaining personal protective equipment", "painting gear"]'::jsonb,2,'Gear must be inspected and cleaned.','original'),
('127.748.d.13.C',4,'Why should damaged PPE be taken out of service?','["It adds weight", "It looks old", "It saves money", "It may not protect the firefighter properly"]'::jsonb,3,'Damaged gear can fail.','original'),
('127.748.d.13.D',3,'Structural gear protects against heat for a limited time but cannot make a firefighter immune to extreme conditions. This describes:','["limitations of PPE", "PPE decoration", "PPE perfection", "PPE absence"]'::jsonb,0,'PPE has limits.','original'),
('127.748.d.13.D',4,'A limitation of firefighter PPE is that it:','["stops all injuries", "cannot protect indefinitely against intense heat or flames", "is unbreakable", "is always perfect"]'::jsonb,1,'Heat can still penetrate.','original'),
('127.748.d.13.E',3,'Wearing heavy gear in a hot building can lead to dehydration and exhaustion. These are:','["gear style", "gear brands", "physical limitations of a firefighter in PPE", "PPE advantages"]'::jsonb,2,'Heat stress is a risk.','original'),
('127.748.d.13.E',4,'Which condition is a risk for firefighters working hard in full PPE?','["sunburn only", "dry mouth only", "frostbite only", "heat exhaustion"]'::jsonb,3,'PPE traps body heat.','original'),
('127.748.d.13.F',3,'A firefighter practices pulling on boots, coat, hood, helmet and gloves within a time limit. This is:','["donning and doffing personal protective equipment", "slowing the response", "avoiding gear", "dressing for school"]'::jsonb,0,'Speed and correctness matter.','original'),
('127.748.d.13.F',4,'A correct donning of PPE leaves:','["flaps open", "no skin exposed and all closures fastened", "skin exposed", "straps loose"]'::jsonb,1,'Full coverage is required.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_95_v1'
from (values
('127.748.d.14.A',3,'A personal alert safety system, or PASS, sounds an alarm if a firefighter stops moving. This is the proper:','["rescue ladder", "siren test", "operation of a PASS device", "radio check"]'::jsonb,2,'PASS alerts others to a downed firefighter.','original'),
('127.748.d.14.A',4,'A PASS device automatically sounds if a firefighter:','["drinks water", "moves quickly", "uses a radio", "remains motionless for a set time"]'::jsonb,3,'Motion sensing triggers the alarm.','original'),
('127.748.d.14.B',3,'Before entering a hazard, a firefighter turns on the PASS and checks that the alarm activates. This is:','["testing the PASS device", "removing the device", "ignoring safety", "skipping checks"]'::jsonb,0,'Test before use.','original'),
('127.748.d.14.B',4,'When testing a PASS device, the firefighter should confirm:','["it is silent", "it activates a loud alarm and resets properly", "it plays music", "it is hot"]'::jsonb,1,'Function must be verified.','original'),
('127.748.d.15.A',3,'A recruit learns that a department has a chief, captains, lieutenants and firefighters. This is the:','["layout of a school", "layout of a hospital", "organization of a fire department", "structure of a bank"]'::jsonb,2,'Departments have a rank structure.','original'),
('127.748.d.15.A',4,'The chain of command in a fire department means that:','["everyone gives orders", "orders are random", "no one gives orders", "orders flow from higher ranks to lower ranks"]'::jsonb,3,'Chain of command ensures order.','original'),
('127.748.d.15.B',3,'A firefighter understands that each member must do assigned tasks so the crew can succeed. This is her role as a:','["member of the fire department", "outsider", "spectator", "visitor"]'::jsonb,0,'Each member contributes.','original'),
('127.748.d.15.B',4,'A firefighter''s duty as a team member includes:','["avoiding training", "following orders and supporting the crew", "ignoring others", "acting alone"]'::jsonb,1,'Teamwork supports safety.','original'),
('127.748.d.15.C',3,'A department''s written rules on uniforms, conduct and attendance are examples of:','["rumors", "suggestions", "rules and regulations common to most fire departments", "jokes"]'::jsonb,2,'Rules set expectations.','original'),
('127.748.d.15.C',4,'Why do fire departments enforce rules and regulations?','["They reduce paperwork", "They limit teamwork", "They are optional", "They promote discipline, safety and consistent performance"]'::jsonb,3,'Order depends on rules.','original'),
('127.748.d.15.D',3,'Most departments state that their mission is to protect life, property and the environment. This is the:','["mission of the fire service", "budget only", "hobby list", "menu of the station"]'::jsonb,0,'Mission statements guide work.','original'),
('127.748.d.15.D',4,'A common mission of a local fire department is to:','["collect taxes", "protect lives and property through prevention and response", "sell supplies", "entertain the public"]'::jsonb,1,'Prevention and response are core.','original'),
('127.748.d.15.E',3,'A department''s standard operating procedures tell firefighters how to handle common situations the same way. This is the function of a:','["logo", "calendar", "standard operating system or procedure", "menu"]'::jsonb,2,'SOPs give consistent guidance.','original'),
('127.748.d.15.E',4,'A benefit of standard operating procedures is that they:','["confuse crews", "delay response", "remove training", "give crews consistent, predictable ways to act"]'::jsonb,3,'Consistency improves safety.','original'),
('127.748.d.15.F',3,'A member assistance program offers counseling and support to firefighters dealing with stress. This is a:','["component of a member assistance program", "fashion program", "food program", "sports program"]'::jsonb,0,'These programs support well-being.','original'),
('127.748.d.15.F',4,'A member assistance program is meant to help firefighters with:','["salary raises", "personal and work-related problems such as stress", "engine repair", "uniform choices"]'::jsonb,1,'They provide confidential support.','original'),
('127.748.d.16.A',3,'At a scene, each firefighter''s name and location is tracked on a board so the incident commander knows who is inside. This is a:','["menu board", "shift schedule", "personnel accountability system", "parking lot map"]'::jsonb,2,'Accountability tracks crew locations.','original'),
('127.748.d.16.A',4,'The purpose of a personnel accountability system is to:','["track gear costs", "assign meals", "list names alphabetically", "know where every firefighter is during an incident"]'::jsonb,3,'It prevents missing firefighters.','original'),
('127.748.d.16.B',3,'Years of exposure to smoke and chemicals can raise a firefighter''s risk of certain illnesses. This is a:','["long-term health consideration of exposure to products of combustion", "style choice", "short-term benefit", "sports injury"]'::jsonb,0,'Exposure has long-term effects.','original'),
('127.748.d.16.B',4,'Which practice helps reduce long-term health risks from fire exposure?','["Skipping decontamination", "Cleaning gear and showering after a fire", "Eating at the scene", "Wearing dirty gear"]'::jsonb,1,'Decontamination reduces exposure.','original'),
('127.748.d.16.C',3,'Slips, strains and burns are common injuries at an emergency scene. These are:','["imaginary", "rare events", "common accidents or injuries in the fire service", "party tricks"]'::jsonb,2,'Injuries often come from falls and strains.','original'),
('127.748.d.16.C',4,'A frequent cause of firefighter injury on the fireground is:','["too little equipment", "too many breaks", "too much rest", "overexertion and slips or falls"]'::jsonb,3,'Strain and falls are common.','original'),
('127.748.d.16.D',3,'Trapped in a room with no light, a firefighter follows the hose line, activates her PASS and calls a Mayday. This is:','["action to take when trapped or disoriented", "panicking", "removing gear", "hiding"]'::jsonb,0,'Disoriented firefighters follow procedures.','original'),
('127.748.d.16.D',4,'If a firefighter becomes lost inside a building, a key first step is to:','["remove the mask", "call a Mayday and stay calm to conserve air", "stop talking", "run blindly"]'::jsonb,1,'Calling a Mayday summons help.','original'),
('127.748.d.17.A',3,'Before entering a burning home, a firefighter shuts off the gas and the electric meter. This is:','["ignoring risk", "adding power", "terminating utility services", "starting a fire"]'::jsonb,2,'Utilities are shut off to reduce hazards.','original'),
('127.748.d.17.A',4,'Why do firefighters shut off utilities at a structure fire?','["They are quiet", "They are free", "They are decorative", "Gas and electricity can feed fires and injure crews"]'::jsonb,3,'Utility hazards are removed.','original'),
('127.748.d.17.B',3,'A downed power line lies across a car. Firefighters should keep back and:','["treat all wires as live and call the utility company", "move it with a tool", "drive over it", "touch the wire"]'::jsonb,0,'Downed lines may be energized.','original'),
('127.748.d.17.B',4,'The safe way to approach a scene with fallen electrical wires is to:','["spray them with water", "stay far away and wait for the utility to de-energize them", "step across", "grab them"]'::jsonb,1,'Water can conduct electricity.','original'),
('127.748.d.17.C',3,'A firefighter inspects a saw''s guard and wears eye protection before cutting. This is:','["unsafe use", "risky shortcuts", "safe handling and operation of hand and power tools", "ignoring safety"]'::jsonb,2,'Safe tool use prevents injuries.','original'),
('127.748.d.17.C',4,'Before using a powered rescue tool, a firefighter should:','["skip checks", "ignore guards", "use it bare-handed", "check it for damage and wear proper protective gear"]'::jsonb,3,'Inspection and PPE are required.','original'),
('127.748.d.17.D',3,'Portable scene lights run from a generator. A safety step is to keep cords and the generator away from standing water. This is:','["safety procedures for fire service lighting equipment", "ignoring cords", "lighting a stage", "avoiding safety"]'::jsonb,0,'Electrical safety applies to lights.','original'),
('127.748.d.17.D',4,'When using a portable generator at an emergency scene, firefighters should:','["leave it unattended", "place it outdoors with ventilation and keep cords out of water", "use damaged cords", "use it indoors"]'::jsonb,1,'Generators produce carbon monoxide.','original'),
('127.748.d.17.E',3,'Riding in an engine, a firefighter fastens a seat belt and wears hearing protection when sirens blare. This is using:','["optional gear", "pranks", "safety equipment on apparatus", "no precautions"]'::jsonb,2,'Belts and earplugs protect crews.','original'),
('127.748.d.17.E',4,'Why must firefighters wear seat belts while the apparatus is moving?','["They slow the truck", "They look nice", "They are optional", "They prevent ejection and serious injuries in crashes"]'::jsonb,3,'Belts save lives.','original'),
('127.748.d.18.A',3,'At a roadway emergency, firefighters wear high-visibility vests and helmets. This is identifying:','["protective equipment and its uses", "street fashion", "office gear", "cleaning supplies"]'::jsonb,0,'Visibility gear protects workers.','original'),
('127.748.d.18.A',4,'A high-visibility vest is worn at roadway scenes so that:','["the vest looks fancy", "drivers can see the firefighters", "the vest keeps them warm", "the vest holds tools"]'::jsonb,1,'Visibility reduces strikes.','original'),
('127.748.d.18.B',3,'Cones, flares and warning lights placed on a roadway are:','["decorations", "lunch items", "traffic and scene control devices", "tools for cooking"]'::jsonb,2,'They direct and warn traffic.','original'),
('127.748.d.18.B',4,'Traffic cones at a crash scene are used to:','["increase speed", "mark parking", "block help", "redirect traffic away from the work area"]'::jsonb,3,'They create a safe zone.','original'),
('127.748.d.18.C',3,'Fuel spills, downed lines and unstable vehicles are examples of:','["structure fire and roadway emergency scene hazards", "picnic items", "sports gear", "decorations"]'::jsonb,0,'Scene hazards must be recognized.','original'),
('127.748.d.18.C',4,'At a roadway emergency, a major hazard to crews is:','["parked cars only", "passing traffic", "the weather forecast only", "quiet streets"]'::jsonb,1,'Traffic causes many injuries.','original'),
('127.748.d.18.D',3,'Parking an engine at an angle to shield the work area is one way to:','["create hazards", "ignore traffic", "mitigate potential scene hazards", "block the street at random"]'::jsonb,2,'Positioning protects crews.','original'),
('127.748.d.18.D',4,'A good way to reduce the danger of fuel leaking at a scene is to:','["add heat", "spread it", "ignore it", "contain the spill and eliminate ignition sources"]'::jsonb,3,'Control spill and ignition.','original'),
('127.748.d.18.E',3,'A crew uses a spotter, wears protective gear and follows a plan when operating at the scene. These are:','["procedures for safe operation at emergency scenes", "guesses", "unsafe habits", "options"]'::jsonb,0,'Safe operation relies on procedures.','original'),
('127.748.d.18.E',4,'A key safe-operation rule at any emergency scene is to:','["work alone", "stay aware of hazards and follow command direction", "ignore orders", "skip PPE"]'::jsonb,1,'Awareness and command maintain safety.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
